import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../context/LanguageContext';
import '../styles/dialogues.css';

const DISPLAY_STYLES = {
  NONE: { display: 'none' },
  INLINE_FLEX: { display: 'inline-flex' }
};

const Dialogues = () => {
  const { t } = useLanguage();
  const [currentDialogue, setCurrentDialogue] = useState('morning_routine');
  const [dialogues, setDialogues] = useState({});
  const [dialogue, setDialogue] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isPaused, setIsPaused] = useState(false);
  const [currentPhraseIndex, setCurrentPhraseIndex] = useState(0);
  const [showTranslations, setShowTranslations] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [volume, setVolume] = useState(0.7);
  const [currentTime, setCurrentTime] = useState(0);
  const [totalTime, setTotalTime] = useState(0);
  const [visibleThemes, setVisibleThemes] = useState(4);
  const [allThemes, setAllThemes] = useState([]);

  const audioElementsRef = useRef([]);
  const currentAudioRef = useRef(null);
  const progressIntervalRef = useRef(null);

  // Load dialogue data
  useEffect(() => {
    const loadDialogueData = async () => {
      try {
        const response = await fetch('/data/data.json');
        const data = await response.json();
        console.log('Data loaded:', data);
        console.log('Data themes:', data.themes);

        if (data?.themes) {
          setAllThemes(data.themes);
          console.log('Themes loaded successfully:', data.themes.length, 'themes');
        }

        // Load initial dialogue
        if (data?.themes && data.themes.length > 0 && data.themes[0].topics && data.themes[0].topics.length > 0) {
          const firstTopic = data.themes[0].topics[0];
          console.log('Loading initial dialogue:', firstTopic.id);
          await loadDialogue(firstTopic.id);
        } else {
          console.log('Using default dialogue:', currentDialogue);
          await loadDialogue(currentDialogue);
        }
        console.log('Initial dialogue loaded successfully');
      } catch (error) {
        console.error('Error loading dialogue data:', error);
        // Set default themes if loading fails
        const defaultThemes = [
          { id: 'morning_routine', title: 'Morning Routine', description: 'Daily morning conversation', icon: 'fas fa-sun', category: 'basic' },
          { id: 'eating_out', title: 'Eating Out', description: 'Restaurant conversation', icon: 'fas fa-utensils', category: 'basic' },
          { id: 'grocery_shopping', title: 'Grocery Shopping', description: 'Shopping conversation', icon: 'fas fa-shopping-cart', category: 'basic' },
          { id: 'booking_flight', title: 'Booking Flight', description: 'Travel booking conversation', icon: 'fas fa-plane', category: 'basic' }
        ];
        setAllThemes(defaultThemes);

        // Still try to load the dialogue even if themes fail
        try {
          await loadDialogue(currentDialogue);
        } catch (dialogueError) {
          console.error('Error loading initial dialogue:', dialogueError);
        }
      }
    };

    loadDialogueData();
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (currentAudioRef.current) {
        currentAudioRef.current.pause();
        currentAudioRef.current = null;
      }

      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
        progressIntervalRef.current = null;
      }
    };
  }, []);

  const loadDialogue = async (dialogueId) => {
    try {
      setCurrentDialogue(dialogueId);
      setIsLoading(true);

      const response = await fetch(`/dialogues/${dialogueId}.txt`);
      if (!response.ok) {
        throw new Error(`Failed to load dialogue: ${response.status}`);
      }

      const content = await response.text();
      const parsedDialogue = parseDialogueTxt(content);

      setDialogue(parsedDialogue);
      setCurrentPhraseIndex(0);
      setCurrentTime(0);
      setTotalTime(0);

      // Stop any currently playing audio
      stopAllAudio();

      // Preload audio files
      await preloadAudios(dialogueId, parsedDialogue);

    } catch (error) {
      console.error('Error loading dialogue:', error);
      setDialogue(null);
    } finally {
      setIsLoading(false);
    }
  };

  const parseDialogueTxt = (content) => {
    const lines = content.split('\n');
    const currentDialogueData = { title: '', lines: [] };
    let currentLine = {};

    for (const rawLine of lines) {
      const line = rawLine.trim();
      if (!line) {
        // Empty line indicates end of current dialogue entry
        if (currentLine.speaker && currentLine.text) {
          dialogue.lines.push(currentLine);
          currentLine = {};
        }
        continue;
      }

      if (line.startsWith('title:')) {
        dialogue.title = line.replace('title:', '').trim();
      } else if (line.startsWith('speaker:')) {
        // Save previous line if exists
        if (currentLine.speaker && currentLine.text) {
          dialogue.lines.push(currentLine);
        }
        currentLine = {
          speaker: line.replace('speaker:', '').trim(),
          text: '',
          translations: {}
        };
      } else if (line.startsWith('text:')) {
        currentLine.text = line.replace('text:', '').trim();
      } else if (line.includes(':') && currentLine && !line.startsWith('title:') && !line.startsWith('speaker:') && !line.startsWith('text:')) {
        // Handle all translation languages dynamically
        const colonIndex = line.indexOf(':');
        const lang = line.substring(0, colonIndex).trim();
        const translation = line.substring(colonIndex + 1).trim();
        currentLine.translations[lang] = translation;
      }
    }

    // Don't forget the last line
    if (currentLine.speaker && currentLine.text) {
      dialogue.lines.push(currentLine);
    }

    return dialogue;
  };

  const playDialogue = async () => {
    if (isPlaying) {
      pauseDialogue();
      return;
    }

    if (isPaused) {
      resumeDialogue();
      return;
    }

    // Check if dialogue is loaded, if not, load it first
    let currentDialogueData = dialogues[currentDialogue];
    if (!currentDialogueData) {
      currentDialogueData = await loadDialogue(currentDialogue);
    }

    if (!dialogue) {
      return;
    }

    // Preload all audio elements like the original JavaScript
    await preloadAudios(dialogue);

    if (dialogue && currentPhraseIndex >= dialogue.lines.length) {
      setCurrentPhraseIndex(0);
      setCurrentTime(0);
    }

    const startIndex = currentPhraseIndex;
    sequentialIndexRef.current = startIndex;
    setIsPlaying(true);
    setIsPaused(false);

    playCurrentPhrase(startIndex);
  };

  // Preload audio function similar to original JavaScript
   const preloadAudios = async (dialogue) => {
     // Clear existing audio elements
     audioElementsRef.current.forEach(audio => {
       if (audio && typeof audio.pause === 'function') {
         audio.pause();
       }
     });

     audioElementsRef.current = [];

     // Create audio elements for each line
     dialogue.lines.forEach((_, index) => {
       const audio = new Audio();
       audio.preload = 'auto';
       audio.src = `/audio/${currentDialogue}/${index + 1}.mp3`;
       audio.volume = isMuted ? 0 : volume;

       audioElementsRef.current.push(audio);
     });
   };

  const pauseDialogue = () => {
    setIsPlaying(false);
    setIsPaused(true);
    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
    }
  };

  const resumeDialogue = () => {
    if (isPaused && currentAudioRef.current) {
      setIsPlaying(true);
      setIsPaused(false);
      currentAudioRef.current.play();
    }
  };

  const stopDialogue = () => {
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(0);
    setCurrentTime(0);

    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
      currentAudioRef.current.currentTime = 0;
      currentAudioRef.current = null;
    }

    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }
  };

  // Create a ref to track current index for sequential playback
  const sequentialIndexRef = useRef(0);

  const playCurrentPhrase = (phraseIndex = null) => {
    const currentDialogueData = dialogues[currentDialogue];
    const indexToPlay = phraseIndex !== null ? phraseIndex : sequentialIndexRef.current;

    if (!currentDialogueData || indexToPlay >= currentDialogueData.lines.length || indexToPlay >= audioElementsRef.current.length) {
      stopDialogue();
      return;
    }

    // Update visual state to match current playing phrase
    setCurrentPhraseIndex(indexToPlay);
    sequentialIndexRef.current = indexToPlay;

    // Use preloaded audio element
    const audio = audioElementsRef.current[indexToPlay];
    if (!audio || !audio.src) {
      // Skip to next phrase
      const nextIndex = indexToPlay + 1;
      if (isPlaying && nextIndex < dialogue.lines.length) {
        setTimeout(() => playCurrentPhrase(nextIndex), 500);
      } else {
        stopDialogue();
      }
      return;
    }

    currentAudioRef.current = audio;
    audio.volume = isMuted ? 0 : volume;

    // Always reset time to play from beginning in sequence
    audio.currentTime = 0;

    // Set up sequential playback
    audio.onended = () => {
      if (isPlaying && sequentialIndexRef.current === indexToPlay) {
        const nextIndex = indexToPlay + 1;
        if (nextIndex < currentDialogueData.lines.length) {
          setTimeout(() => playCurrentPhrase(nextIndex), 500);
        } else {
          stopDialogue();
        }
      }
    };

    const playPromise = audio.play();

    if (playPromise !== undefined) {
      playPromise.then(() => {
        // Audio playing successfully
      }).catch(error => {
        // Skip to next phrase even with error
        const nextIndex = indexToPlay + 1;
        if (isPlaying && nextIndex < currentDialogueData.lines.length) {
          setTimeout(() => playCurrentPhrase(nextIndex), 500);
        } else {
          stopDialogue();
        }
      });
    }
  };

  const getCurrentPlaybackTime = () => {
    const currentDialogueData = dialogues[currentDialogue];
    if (!currentDialogueData) return 0;

    let time = 0;

    // Add duration of completed phrases
    for (let i = 0; i < currentPhraseIndex; i++) {
      const wordCount = currentDialogueData.lines[i].text.split(' ').length;
      time += Math.max(2, wordCount * 0.5);
    }

    // Add current phrase progress
    if (currentAudioRef.current && !isNaN(currentAudioRef.current.currentTime)) {
      time += currentAudioRef.current.currentTime;
    }

    return time;
  };

  const toggleTranslations = () => {
    setShowTranslations(prev => !prev);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const toggleMute = () => {
    setIsMuted(prev => !prev);
    if (currentAudioRef.current) {
      currentAudioRef.current.volume = isMuted ? volume : 0;
    }
  };

  const handleVolumeChange = (e) => {
    const newVolume = parseFloat(e.target.value);
    setVolume(newVolume);
    if (currentAudioRef.current && !isMuted) {
      currentAudioRef.current.volume = newVolume;
    }
  };



  const loadMoreThemes = () => {
    setVisibleThemes(prev => Math.min(prev + 4, allThemes.length));
  };

  const showLessThemes = () => {
    setVisibleThemes(4);
  };

  const handleProgressBarClick = (e) => {
    const currentDialogueData = dialogues[currentDialogue];
    if (!currentDialogueData) return;

    const progressBar = e.currentTarget;
    const rect = progressBar.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const progressWidth = rect.width;
    const clickPercentage = clickX / progressWidth;
    const targetTime = clickPercentage * totalTime;

    // Find which phrase this time corresponds to
    let accumulatedTime = 0;
    let targetPhraseIndex = 0;

    for (let i = 0; i < currentDialogueData.lines.length; i++) {
      const wordCount = currentDialogueData.lines[i].text.split(' ').length;
      const phraseDuration = Math.max(2, wordCount * 0.5);

      if (accumulatedTime + phraseDuration >= targetTime) {
        targetPhraseIndex = i;
        break;
      }

      accumulatedTime += phraseDuration;
      targetPhraseIndex = i + 1;
    }

    // Update current phrase and time
    setCurrentPhraseIndex(targetPhraseIndex);
    setCurrentTime(targetTime);

    // If playing, restart from new position
     if (isPlaying) {
       playCurrentPhrase();
     }
   };

   const playSpecificPhrase = (phraseIndex) => {
    const currentDialogueData = dialogues[currentDialogue];
    if (!currentDialogueData || phraseIndex >= currentDialogueData.lines.length) return;

    // Stop any ongoing playback completely
    if (currentAudioRef.current) {
      currentAudioRef.current.pause();
      currentAudioRef.current = null;
    }
    if (progressIntervalRef.current) {
      clearInterval(progressIntervalRef.current);
    }

    // Reset states to ensure clean single phrase playback
    setIsPlaying(false);
    setIsPaused(false);
    setCurrentPhraseIndex(phraseIndex);

    // Calculate time up to this phrase
    let timeToPhrase = 0;
    for (let i = 0; i < phraseIndex; i++) {
      const wordCount = currentDialogueData.lines[i].text.split(' ').length;
      timeToPhrase += Math.max(2, wordCount * 0.5);
    }
    setCurrentTime(timeToPhrase);

    // Play only this specific phrase (single phrase mode)
    const audioUrl = `/audio/${currentDialogue}/${phraseIndex + 1}.mp3`;
    const audio = new Audio(audioUrl);

    audio.volume = isMuted ? 0 : volume;
    currentAudioRef.current = audio;

    // Start progress tracking for single phrase
    const startProgressTracking = () => {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }

      progressIntervalRef.current = setInterval(() => {
        if (audio && !audio.paused && !audio.ended) {
          const currentPlaybackTime = getCurrentPlaybackTime();
          setCurrentTime(currentPlaybackTime);
        }
      }, 100);
    };

    audio.onloadedmetadata = () => {
      startProgressTracking();
    };

    // Single phrase mode - do NOT continue automatically
    audio.onended = () => {
      if (progressIntervalRef.current) {
        clearInterval(progressIntervalRef.current);
      }
      // Reset playing state when single phrase ends
      setIsPlaying(false);
      setIsPaused(false);
      currentAudioRef.current = null;
    };

    audio.onerror = () => {
      console.warn(`Audio not found: ${audioUrl}`);
      // Simulate single phrase duration
      const wordCount = currentDialogueData.lines[phraseIndex].text.split(' ').length;
      const duration = Math.max(2, wordCount * 0.5) * 1000;

      setTimeout(() => {
        setIsPlaying(false);
        setIsPaused(false);
      }, duration);
    };

    // Temporarily set playing state for this phrase only
    setIsPlaying(true);
    setIsPaused(false);

    audio.play().catch(error => {
      console.error('Audio playback failed:', error);
      setIsPlaying(false);
    });
  };

  const formatTime = (seconds) => {
    if (isNaN(seconds)) return "0:00";
    const mins = Math.floor(seconds / 60);
    const secs = Math.floor(seconds % 60);
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  };

  // Update dialogue when dialogues or currentDialogue changes
  useEffect(() => {
    if (dialogues[currentDialogue]) {
      setDialogue(dialogues[currentDialogue]);
    }
  }, [dialogues, currentDialogue]);

  return (
    <div className={`dialogues-page ${showTranslations ? 'show-translations' : ''}`}>
      <div className="container">
        <div className="dialogue-container">
          <div className="dialogue-header">
            <h1 className="dialogue-title">
            {dialogue?.title || 'Loading...'}
          </h1>

          <div className="dialogue-controls">
          </div>
        </div>

        <div className="dialogue-content">
          {dialogue?.lines?.map((line, index) => (
            <div 
              key={index}
              className={`message message-${index % 2 === 0 ? 'other' : 'user'} ${
                currentPhraseIndex === index && isPlaying ? 'highlighted playing' : ''
              }`}
              data-index={index}
              onClick={() => playSpecificPhrase(index)}
              style={{ cursor: 'pointer' }}
            >
              <div className="message-info">
                <span className="message-sender">{line.speaker}</span>
              </div>
              <div className="message-content">
                <div className="message-text">{line.text}</div>
                {showTranslations && (
                  <div className="translation-text">
                    {line.translations?.pt || line.translations?.es || line.translations?.en || ''}
                  </div>
                )}
              </div>
            </div>
          )) || (
            <div className="message message-info">
              <div className="message-content">
                <div className="message-text">Carregando diálogo...</div>
              </div>
            </div>
          )}
        </div>

        {/* Media Player - Always visible */}
        <div className="media-player">
          <div className="player-controls">
            <button 
              id="play-btn"
              className="player-btn"
              onClick={playDialogue}
              style={isPlaying ? DISPLAY_STYLES.NONE : DISPLAY_STYLES.INLINE_FLEX}
            >
              <i className="fas fa-play"></i>
            </button>

            <button 
              id="pause-btn"
              className="player-btn"
              onClick={pauseDialogue}
              style={isPlaying ? DISPLAY_STYLES.INLINE_FLEX : DISPLAY_STYLES.NONE}
            >
              <i className="fas fa-pause"></i>
            </button>

            <button 
              id="stop-btn"
              className="player-btn"
              onClick={stopDialogue}
            >
              <i className="fas fa-stop"></i>
            </button>

            <button 
              id="translate-toggle-btn"
              className="player-btn"
              onClick={toggleTranslations}
            >
              <i className="fas fa-language"></i>
            </button>

            <button 
              id="fullscreen-toggle-btn"
              className="player-btn"
              onClick={toggleFullscreen}
            >
              <i className={`fas ${isFullscreen ? 'fa-compress' : 'fa-expand'}`}></i>
            </button>

            <div className="volume-control">
              <button 
                id="volume-btn"
                className="volume-btn"
                onClick={toggleMute}
              >
                <i className={`fas ${isMuted ? 'fa-volume-mute' : 'fa-volume-up'}`}></i>
              </button>
              <input 
                id="volume-slider"
                type="range"
                className="volume-slider"
                min="0"
                max="1"
                step="0.1"
                value={volume}
                onChange={handleVolumeChange}
              />
            </div>
          </div>

          <div className="progress-container">
            <div 
              id="progress-bar"
              className="progress-bar"
              onClick={handleProgressBarClick}
              style={{ '--progress': `${totalTime > 0 ? (currentTime / totalTime) * 100 : 0}%` }}
            ></div>
            <div className="time-display">
              <span id="current-time">{formatTime(currentTime)}</span> <span id="total-time">{formatTime(totalTime)}</span>
            </div>
          </div>
        </div>
      </div>

      <div className="themes-section">
        <h2 className="section-title">Choose a Dialogue Theme</h2>

        <div className="theme-grid" id="theme-container">
          {allThemes.slice(0, visibleThemes).map((theme, index) => (
            <div 
              key={`theme-${index}`}
              className="theme-card"
            >
              <h3>{theme.title}</h3>
              <ul>
                {theme.topics && theme.topics.map((topic, topicIndex) => (
                  <li 
                    key={`topic-${topicIndex}`}
                    onClick={() => loadDialogue(topic.id)}
                    data-id={topic.id}
                    className={currentDialogue === topic.id ? 'active' : ''}
                  >
                    {topic.name}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        {/* Theme Controls */}
        <div className="theme-controls">
          {visibleThemes < allThemes.length && (
            <button 
              id="load-more-btn"
              className="theme-control-btn"
              onClick={loadMoreThemes}
            >
              <span data-translate="loadMore">Load More</span>
            </button>
          )}

          {visibleThemes > 4 && (
            <button 
              id="show-less-btn"
              className="theme-control-btn"
              onClick={showLessThemes}
              style={{ marginLeft: '1rem' }}
            >
              <span data-translate="showLess">Show Less</span>
            </button>
          )}
        </div>
      </div>
    </div>
  </div>
  );
};

export default Dialogues;
